  <template v-else>
    <ApplicationsDetailsTable
      v-if="isUpcomingProjectPricingForManagerOrAdmin(projectDetails.pricing)"
      :payment="projectDetails.pricing"
      :project-id="projectDetails.id"
      :project-name="projectDetails.name"
      :project-type="projectDetails.type"
      :payment-enabled="projectDetails.pricing.payments_enabled"
    />
  </template>
</template>

<script setup lang="ts">
import { type ProjectShortInfo, type ProjectEditTabsStatusResponse } from '~/client';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
